WITH filtered AS (SELECT *, CEIL(monthly_fee) AS monthly_fee_whole FROM subscriptions WHERE end_date > DATE '2023-11-09') SELECT CASE WHEN monthly_fee_whole >= 75 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_whole_tier, plan, CASE WHEN monthly_fee >= 254 THEN 'PREMIUM' ELSE 'STANDARD' END AS monthly_fee_tier, ROUND(SUM(monthly_fee) / NULLIF(COUNT(CASE WHEN status = 'PAUSED' THEN 1 END), 0), 2) AS monthly_fee_per_paused, COUNT(DISTINCT id) AS distinct_ids, SUM(monthly_fee_whole) FILTER (WHERE status = 'CANCELLED') AS cancelled_total_monthly_fee_whole FROM filtered GROUP BY ROLLUP (CASE WHEN monthly_fee_whole >= 75 THEN 'LARGE' ELSE 'SMALL' END, plan, CASE WHEN monthly_fee >= 254 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING SUM(monthly_fee_whole) FILTER (WHERE status = 'CANCELLED') < 1000000 ORDER BY plan
